// PDOK Locatieserver access for the kiosk.
//
// PDOK is the Dutch government geocoder. It is used here for two things: letting
// the visitor search for a municipality or postcode, and resolving a tapped map
// point to a postcode. The transport layer (fetch, SWR hooks, request params and
// the response envelope) is generated by orval in `./pdok`; this file only adds
// the domain knowledge the OpenAPI spec does not describe.
import { free, lookup, reverseGeocoder, useFree, type ResponseDocsItem } from './pdok/generated';

// The subset of a PDOK result document this app reads.
// The spec types every result as `{ [key: string]: unknown }`, so the fields we
// actually rely on are spelled out here and narrowed at the boundary below.
type PdokDoc = {
    id?: string; // stable PDOK object id; the Lookup API fetches by this
    type?: string; // "gemeente", "postcode", "adres", ...
    weergavenaam?: string; // human-readable label, e.g. "Gemeente Rotterdam"
    postcode?: string; // e.g. "1011AB" (no space), on postcode/address results
    centroide_ll?: string; // centroid as WKT, e.g. "POINT(4.90 52.37)"
};

// One place the search box can offer, and that the map can fly to.
export type PlaceSuggestion = {
    id: string;
    label: string;
    type: string;
    center: [number, number] | null; // [longitude, latitude], null when unknown
};

// The query shared by the search function and its SWR hook.
// `fq` keeps PDOK to municipalities and postcodes (not streets or addresses),
// `fl` trims the response to the fields we read, and `rows` caps the list.
const SEARCH_PARAMS = {
    fq: ['type:(gemeente OR postcode)'],
    fl: 'id type weergavenaam postcode centroide_ll',
    rows: 8,
};

// A PDOK result is `{ [key: string]: unknown }`; assert the declared shape.
const asPdokDoc = (doc: ResponseDocsItem): PdokDoc => doc as PdokDoc;

// A result only becomes a suggestion when it has both an id and a label; this
// guard also narrows those two fields from optional to required for callers.
function isPlaceDoc(doc: PdokDoc): doc is PdokDoc & { id: string; weergavenaam: string } {
    return typeof doc.id === 'string' && typeof doc.weergavenaam === 'string';
}

// PDOK returns centroids as WKT ("POINT(lng lat)"); pull out the two numbers.
// A missing or malformed value yields null, so the suggestion just can't fly to.
function parseCentroide(value: string | undefined): [number, number] | null {
    const match = /POINT\(([-\d.]+) ([-\d.]+)\)/.exec(value ?? '');
    return match ? [Number(match[1]), Number(match[2])] : null;
}

// Turn a PDOK `docs` array into the suggestion shape the UI consumes.
function toSuggestions(docs: ResponseDocsItem[] | undefined): PlaceSuggestion[] {
    return (docs ?? [])
        .map(asPdokDoc) // trust the declared field shape
        .filter(isPlaceDoc) // drop entries without an id or label
        .map((doc) => ({
            id: doc.id,
            label: doc.weergavenaam,
            type: doc.type ?? '',
            center: parseCentroide(doc.centroide_ll),
        }));
}

// Free-text search over Dutch municipalities and postcodes, for imperative use.
// Lives beside `usePlaceSearch` so non-component callers have a plain promise.
export async function searchPlaces(query: string): Promise<PlaceSuggestion[]> {
    // A blank query is not worth a request; PDOK would try to match everything.
    const q = query.trim();
    if (q.length === 0) return [];

    // `free` is the generator's request function. Its result is a discriminated
    // union on `status`, so any non-200 response collapses to an empty list.
    const res = await free({ ...SEARCH_PARAMS, q });
    return res.status === 200 ? toSuggestions(res.data.response?.docs) : [];
}

// The search as an SWR hook for the search box.
// SWR keys the request on the query params, so each query (after the caller's
// debounce) fetches once and repeats come from cache. `keepPreviousData` keeps
// the current list on screen while the next one loads, so the dropdown does not
// flicker between keystrokes.
export function usePlaceSearch(query: string) {
    const q = query.trim();
    const { data, error, isLoading } = useFree(
        { ...SEARCH_PARAMS, q },
        // `enabled` gates the request, so an empty query never reaches PDOK.
        { swr: { enabled: q.length > 0, keepPreviousData: true } },
    );

    // Only a 200 carries a `response`; anything else means "no suggestions".
    const places = data && data.status === 200 ? toSuggestions(data.data.response?.docs) : [];
    return { places, isLoading, error };
}

// The postcode at a coordinate — the value behind "where do you live?".
// This is a two-step PDOK lookup: `reverse` finds the nearest postcode object to
// the point but only exposes the postcode inside its display name, so `lookup`
// then fetches that same object by id to read the clean `postcode` field.
// Returns null when the point has no postcode or a request fails.
export async function reversePostcode(lng: number, lat: number): Promise<string | null> {
    // Step 1: nearest postcode object to the tapped point (lon/lat in WGS84).
    const reverse = await reverseGeocoder({ lon: lng, lat, type: 'postcode', rows: 1 });
    if (reverse.status !== 200) return null;

    // The object id is what step 2 needs; without it there is nothing to resolve.
    const id = (reverse.data.response?.docs ?? []).map(asPdokDoc)[0]?.id;
    if (!id) return null;

    // Step 2: resolve the object to its clean `postcode` field.
    const detail = await lookup({ id, fl: 'postcode' });
    if (detail.status !== 200) return null;

    return (detail.data.response?.docs ?? []).map(asPdokDoc)[0]?.postcode ?? null;
}
